#!/bin/sh
# Generate external/configs/microlinux_<arch>_defconfig from
# external/configs/fragments/common.config + <arch>.config + repo.config.
# Edit the fragments, not the generated files. scripts/build.sh runs this.
set -e
C="$(dirname "$0")/../external/configs"
for f in "$C"/fragments/*.config; do
	a=$(basename "$f" .config)
	case "$a" in common|repo) continue ;; esac
	{
		echo "# MicroLinux $a - Buildroot defconfig. GENERATED by scripts/gen-defconfigs.sh"
		echo "# from configs/fragments/{common,$a,repo}.config: edit those."
		echo "# Build:  make BR2_EXTERNAL=<src>/external microlinux_${a}_defconfig && make"
		echo
		cat "$f"
		echo
		cat "$C/fragments/common.config"
		echo
		cat "$C/fragments/repo.config"
	} > "$C/microlinux_${a}_defconfig.tmp"
	mv "$C/microlinux_${a}_defconfig.tmp" "$C/microlinux_${a}_defconfig"
done
